// @receive light
// @watch night
let light = 512;
let night = 0;
let lastButton = false;
let brightness = 0.5;
let dayMix = 0;

function setup() {
  createCanvas(600, 380);
  noStroke();
}

function acceptLine(line) {
  const reading = String(line).trim().match(/^light=(\d+) button=([01]) led=[01]$/);
  if (!reading) return;
  light = constrain(Number(reading[1]), 0, 1023);
  const pressed = reading[2] === '1';
  if (pressed && !lastButton) night = 1 - night;
  lastButton = pressed;
}

function draw() {
  arduinoComms.poll();
  brightness = lerp(brightness, light / 1023, 0.09);
  dayMix = lerp(dayMix, night, 0.08);
  const shade = (day, dark) => lerpColor(color(day), color(dark), dayMix);
  const skyTop = shade('#62b9ec', '#111735');
  const skyBottom = shade('#f6dfae', '#444366');
  for (let y = 0; y < height; y += 2) {
    fill(lerpColor(skyTop, skyBottom, y / height));
    rect(0, y, width, 2);
  }

  const stars = [[42,44],[98,91],[164,39],[257,66],[330,38],[380,112],[473,38],[554,83],[527,146]];
  fill(255, 240, 199, dayMix * 220);
  for (const [x,y] of stars) circle(x, y, x % 3 + 2);

  // The smoothed photocell reading moves the sun or moon along the same arc.
  const skyX = lerp(55, width - 55, brightness);
  const skyY = 175 - 115 * sin(PI * brightness);
  fill(shade('#ffd063', '#f3eddc'));
  circle(skyX, skyY, 76);
  const crescent = lerpColor(skyTop, skyBottom, (skyY - 12) / height);
  crescent.setAlpha(dayMix * 255);
  fill(crescent);
  circle(skyX + 19, skyY - 12, 64);

  fill(shade('#87a573', '#394563'));
  ellipse(440, 390, 580, 265);
  fill(shade('#587c49', '#25374a'));
  ellipse(180, 420, 650, 370);

  stroke(shade('#684630', '#292332'));
  strokeCap(ROUND);
  strokeWeight(17);
  line(220, 269, 215, 152);
  strokeWeight(9);
  line(217, 207, 182, 171);
  line(216, 193, 251, 158);
  noStroke();
  fill(shade('#346451', '#294859'));
  ellipse(214, 140, 121, 102);
  ellipse(174, 158, 79, 69);
  ellipse(253, 156, 81, 72);
  fill(shade('#60936a', '#385b68'));
  ellipse(193, 129, 68, 55);
  ellipse(237, 128, 71, 61);
  fill(shade('#8ab17d', '#50737a'));
  ellipse(209, 109, 52, 35);

  fill(4, 11, 24, 145 * (1 - brightness));
  rect(0, 0, width, height);
  fill(7, 16, 28, 175);
  rect(16, 334, 254, 30, 6);
  fill('#fff6dd');
  textSize(13);
  text((night ? 'NIGHT' : 'DAY') + '   ·   LIGHT ' + light + ' / 1023', 27, 354);
}

