// A0 reads the junction of the photoresistor and 10 kΩ resistor.
// D7 uses the internal pull-up. Pressing the button connects it to GND.
const int LIGHT_PIN = A0;
const int BUTTON_PIN = 7;
const int LED_PIN = 13;
const int DARK_THRESHOLD = 350;

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(LIGHT_PIN);
  bool pressed = digitalRead(BUTTON_PIN) == LOW;
  bool ledOn = pressed || light < DARK_THRESHOLD;
  digitalWrite(LED_PIN, ledOn ? HIGH : LOW);

  Serial.print("light=");
  Serial.print(light);
  Serial.print(" button=");
  Serial.print(pressed ? 1 : 0);
  Serial.print(" led=");
  Serial.println(ledOn ? 1 : 0);
  delay(200);
}

